using FluentValidation; using MediatR; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities; using Microsoft.EntityFrameworkCore;
namespace InventorySystem.Application.Features.Products.Commands;
public record CreateProductCommand(string Name,string SKU,string? Barcode,string? Description,decimal PurchasePrice,decimal SellingPrice,int MinimumStock,int CategoryId) : IRequest<int>;
public class CreateProductCommandValidator : AbstractValidator<CreateProductCommand> { public CreateProductCommandValidator(){ RuleFor(x=>x.Name).NotEmpty().MaximumLength(200); RuleFor(x=>x.SKU).NotEmpty().MaximumLength(50); RuleFor(x=>x.PurchasePrice).GreaterThanOrEqualTo(0); RuleFor(x=>x.SellingPrice).GreaterThanOrEqualTo(0); RuleFor(x=>x.MinimumStock).GreaterThanOrEqualTo(0); RuleFor(x=>x.CategoryId).GreaterThan(0); } }
public class CreateProductCommandHandler(IAppDbContext db) : IRequestHandler<CreateProductCommand,int> { public async Task<int> Handle(CreateProductCommand r,CancellationToken ct){ if(await db.Products.AnyAsync(x=>x.SKU==r.SKU&&!x.IsDeleted,ct)) throw new InvalidOperationException("SKU already exists."); var p=new Product{Name=r.Name,SKU=r.SKU,Barcode=r.Barcode,Description=r.Description,PurchasePrice=r.PurchasePrice,SellingPrice=r.SellingPrice,MinimumStock=r.MinimumStock,CategoryId=r.CategoryId}; db.Products.Add(p); await db.SaveChangesAsync(ct); return p.Id; } }
